  const view=()=>runtime.projections.workspace(actor,contextId);const command=async(operation:WorkspaceCommand['operation'])=>{const c=await view();return runtime.workspace.handle(actor,{commandId:randomUUID(),intentVersion:1,target:{contextId,contextGeneration:c.contextGeneration,tabId:actor.tabId,expectedOwnerRevision:c.ownerRevision,expectedWorkspaceRevision:c.workspaceRevision},operation});};
  const c=await view();const prepared=await runtime.files.prepare(actor,{commandId:randomUUID(),intentVersion:1,purpose:'PAGE_IMAGES',target:{contextId,contextGeneration:c.contextGeneration,tabId:actor.tabId,expectedOwnerRevision:c.ownerRevision,expectedWorkspaceRevision:c.workspaceRevision}});
  const pixels=Buffer.alloc(400*260*4);for(let y=0;y<260;y++)for(let x=0;x<400;x++){const at=(y*400+x)*4;pixels[at]=x%251;pixels[at+1]=y%241;pixels[at+2]=(x+y)%239;pixels[at+3]=x<20?128:255;}const original=await sharp(pixels,{raw:{width:400,height:260,channels:4}}).png().toBuffer();const preview=await runtime.files.receive(actor,prepared.operationRef.id!,randomUUID(),'owned.png',original);await command({kind:'COMMIT_UPLOAD',payload:{uploadId:preview.uploadId,previewRevision:preview.previewRevision,candidateIdsInOrder:preview.candidateIdsInOrder,explicitDuplicateIds:[]}});const pageId=(await admin.pool.query('SELECT page_lineage_id FROM manga_web.workspace_pages WHERE account_id=$1',[actor.accountId])).rows[0].page_lineage_id as string;
