  const current=async()=>(await admin.pool.query<ResultRow>('SELECT r.* FROM manga_web.results r JOIN manga_web.workspace_pages p ON p.account_id=r.account_id AND p.current_result_id=r.result_id WHERE p.account_id=$1 AND p.page_lineage_id=$2',[actor.accountId,pageId])).rows[0];
  const request=async(scope:Extract<WorkspaceCommand['operation'],{kind:'REQUEST_TRANSLATION'}>['payload']['scope']={kind:'PAGE'})=>command({kind:'REQUEST_TRANSLATION',payload:{pageId,scope,expectedResultRevision:(await current()).result_revision,settingsVersion:(await admin.pool.query('SELECT current_settings_revision FROM manga_web.workspace_contexts WHERE context_id=$1',[contextId])).rows[0].current_settings_revision as string}});
