  const service=(adapter=pipeline(),hooks:ConstructorParameters<typeof ExecutionService>[3]={})=>new ExecutionService(runtime.options.worker,adapter,runtime.options.policy,hooks);
  const until=async(stage:string,execution=runtime.execution)=>{for(let i=0;i<40;i++){if((await admin.pool.query("SELECT 1 FROM manga_web.executions WHERE logical_step_id=$1 AND state='SUCCEEDED'",[stage])).rowCount)return;if(!await execution.runOnce())throw Error(`Stage ${stage} did not succeed`);}throw Error('Pipeline stage did not finish');};
