    const row=(await f.admin.pool.query("SELECT execution_id,state,finished_confirmed_at,output_envelope FROM manga_web.executions WHERE logical_step_id='CLEANUP'")).rows[0];expect(row).toMatchObject({state:'UNKNOWN',finished_confirmed_at:null,output_envelope:{outcome:'UNKNOWN',started:true,costUsd:null,usageConfirmed:false,data:null}});const input=(await f.admin.pool.query("SELECT protected_observation FROM manga_web.execution_evidence WHERE execution_id=$1 AND kind='INPUT'",[row.execution_id])).rows[0].protected_observation as StageInput;
    const evidence=(await f.admin.pool.query("SELECT evidence_digest,protected_observation FROM manga_web.execution_evidence WHERE execution_id=$1 AND kind='LOCAL_NATIVE_FAILURE'",[row.execution_id])).rows;expect(evidence).toHaveLength(1);expect(evidence[0].evidence_digest).toBe(digest(evidence[0].protected_observation));const captured=structuredClone(input);delete captured.claimGeneration;expect(evidence[0].protected_observation).toMatchObject({version:1,executionId:input.executionId,inputDigest:input.inputDigest,inputFingerprint:digest(captured),stage:'CLEANUP',errorCode:item.code,termination:{...native.error.termination},observation:{outcome:'UNKNOWN',started:true,costUsd:null,usageConfirmed:false,data:null}});
    const start=(await f.admin.pool.query("SELECT evidence_digest,protected_observation FROM manga_web.execution_evidence WHERE execution_id=$1 AND kind='START'",[row.execution_id])).rows;expect(start).toHaveLength(1);expect((await f.admin.pool.query("SELECT state,actual_usd FROM manga_web.cost_items WHERE execution_id=$1 AND component='LOCAL_SYNTHETIC'",[row.execution_id])).rows[0]).toEqual({state:'UNCONFIRMED',actual_usd:null});
    f.advance(5000);const fresh=fakeNative(f.original,item);const resumed=f.pipeline({},new SyntheticProvider(),fresh.native);await expect(resumed.lookup(input.executionId,input)).resolves.toMatchObject({outcome:'UNKNOWN',started:true,costUsd:null,usageConfirmed:false,data:null});await drain(f.service(resumed));
