    f.advance(31000);const fresh=fakeNative(f.original,nativeFailures[1]);const resumed=f.pipeline({},new SyntheticProvider(),fresh.native);await drain(f.service(resumed));await expect(resumed.lookup(input!.executionId,input!)).resolves.toMatchObject({outcome:'UNKNOWN',started:true,costUsd:null,usageConfirmed:false,data:null});expect((await f.admin.pool.query(capacitySql,[input!.executionId])).rows).toEqual(capacity);expect((await f.admin.pool.query(budgetSql,[input!.requestId])).rows).toEqual(budget);expect((await f.admin.pool.query('SELECT count(*) AS n FROM manga_web.execution_limit_expenses WHERE execution_id=$1',[input!.executionId])).rows[0].n).toBe('0');expect((await f.admin.pool.query("SELECT state,actual_usd FROM manga_web.cost_items WHERE execution_id=$1 AND component='LOCAL_SYNTHETIC'",[input!.executionId])).rows[0]).toEqual({state:'UNCONFIRMED',actual_usd:null});expect((await f.admin.pool.query('SELECT count(*) AS n FROM manga_web.checkpoints WHERE execution_id=$1',[input!.executionId])).rows[0].n).toBe('0');expect((await f.current()).result_id).toBe(before.result_id);expect(put).not.toHaveBeenCalled();expect(native.cleanup).toHaveBeenCalledOnce();expect(fresh.cleanup).not.toHaveBeenCalled();expect(native.run).not.toHaveBeenCalled();expect(fresh.run).not.toHaveBeenCalled();
